// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public { c = new X_WALLET(address(new Log())); }

    // fuzzed params: actor (address) and amount to try to Collect
    // We will arrange for actor to have a deposit < MinSum so the reference's Collect will simply return (no revert),
    // while the mutant's require will revert. We must not hard-code amounts; fuzz provides them.
    function testFuzz_property(address actor, uint256 deposit, uint256 tryCollect) public {
        vm.assume(deposit <= VALUE_CAP);
        // keep actor non-zero
        vm.assume(actor != address(0));
        // ensure deposit is small so deposit < MinSum (MinSum is 1 ether). Keep wide: require deposit < 1 ether
        vm.assume(deposit < 1 ether);
        // tryCollect can be any value; keep it <= deposit to avoid immediate balance-check difference on that predicate
        // but we don't need to force that; keep wide but bound to a reasonable size so sending succeeds in test
        tryCollect = bound(tryCollect, 0, 1 ether - 1);

        // fund actor so they can call Put with value 'deposit'
        vm.deal(actor, deposit);
        vm.startPrank(actor);
        // Actor calls Put to register a small balance (< MinSum)
        // forward deposit value (may be zero)
        c.Put{value: deposit}(block.timestamp);
        vm.stopPrank();

        // Now attempt to Collect tryCollect from actor.
        // The reference contract's Collect will check `if (acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime)`
        // If the condition is false (true here because acc.balance < MinSum), reference returns normally (no revert).
        // The mutant changes that to `require(...)` which will revert. We detect this by try/catch and assert that
        // the call succeeded (no revert) on the reference for all such inputs — our assertion reads the success flag.

        bool ok;
        vm.startPrank(actor);
        try c.Collect{value: 0}(tryCollect) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: for ANY actor and deposit < MinSum and any tryCollect in range, the reference C does NOT revert,
        // so ok must be true. The mutant will revert for some of these inputs (making ok false), so this single assert distinguishes them.
        assertTrue(ok);
    }
}

